// Adapted from mastermorphic morphic/lib/tools/todo.ts:29-59 @ c9b8310: the `ai` tool() wrapper is a
// plain object and the zod input schema (todo.ts:4-27) is left out. That schema gives every todo a
// priority (enum, default 'medium') and describes `todos` as "The complete list of todos". The execute
// body is verbatim.
export function createTodoTools() {
  // Session-scoped todos storage - isolated per tool instance
  let sessionTodos = []
  const todoWrite = {
    description:
      'Create or update todos to track progress on complex tasks. Use this to maintain a list of action items. The response includes completedCount and totalCount to verify task completion.',
    execute: async ({ todos, progressMessage }) => {
      // Update session todos - ensure priority is always set
      sessionTodos = todos.map(todo => ({
        ...todo,
        priority: todo.priority || 'medium'
      }))

      // Calculate progress
      const completedCount = todos.filter(t => t.status === 'completed').length
      const totalCount = todos.length

      return {
        success: true,
        message: progressMessage || `Updated ${totalCount} todos`,
        completedCount,
        totalCount,
        todos: sessionTodos
      }
    }
  }

  return { todoWrite }
}

